const js = `(() => {
  'use strict';
  const {title:wikiTitle,pages,sections} = JSON.parse(document.getElementById('wiki-data').textContent);
  const byId = new Map(pages.map(p=>[p.id,p]));
  const $ = id => document.getElementById(id);
  const colorScheme = matchMedia('(prefers-color-scheme: dark)');
  const colorInputs = document.querySelectorAll('input[name="color"]');
  function setColor(preference) {
    if (!['automatic', 'light', 'dark'].includes(preference)) preference = 'automatic';
    document.documentElement.dataset.colorPreference = preference;
    document.documentElement.dataset.theme = preference === 'automatic' ? (colorScheme.matches ? 'dark' : 'light') : preference;
    colorInputs.forEach(input => { input.checked = input.value === preference; });
  }
  setColor(document.documentElement.dataset.colorPreference);
  colorInputs.forEach(input => input.addEventListener('change', () => {
    setColor(input.value);
    try { localStorage.setItem('planning-wiki-color', input.value); } catch {}
  }));
  colorScheme.addEventListener('change', () => setColor(document.documentElement.dataset.colorPreference));
  window.addEventListener('storage', event => {
    if (event.key === 'planning-wiki-color' || event.key === null) setColor(event.newValue);
  });
  document.addEventListener('click', event => {
    if (!$('appearance').contains(event.target)) $('appearance').open = false;
  });
  document.addEventListener('keydown', event => {
    if (event.key === 'Escape' && $('appearance').open) {
      $('appearance').open = false;
      $('appearance').querySelector('summary').focus();
    }
  });
  let current = null;
  const link = (label,href) => { const a=document.createElement('a'); a.textContent=label; a.href=href; return a; };
  const route = id => '#/'+id.split('/').map(s=>encodeURIComponent(s).replace(/~/g,'%7E')).join('/');
  for (const section of sections) {
    const group=document.createElement('div');group.className='nav-group';
    const label=document.createElement('div');label.className='nav-group-label';label.textContent=section;group.append(label);
    pages.filter(p=>p.section===section).forEach(p=>{const a=link(p.id==='index'?'Main page':p.title,route(p.id));a.dataset.page=p.id;group.append(a);});
    $('navigation').append(group);
  }
  if (matchMedia('(max-width: 700px)').matches) $('navigation-details').open=false;
  function mode(source) {
    $('article-view').hidden=source;
    $('source-view').hidden=!source;
    $('read-tab').classList.toggle('selected',!source);
    $('source-tab').classList.toggle('selected',source);
    $('read-tab').setAttribute('aria-pressed',String(!source));
    $('source-tab').setAttribute('aria-pressed',String(source));
    $('contents').hidden=source || !current?.toc.length;
  }
  function markText(text,query) {
    const fragment=document.createDocumentFragment();
    const lower=text.toLowerCase(), needle=query.toLowerCase();
    let start=0, at;
    while (needle && (at=lower.indexOf(needle,start))!==-1) {
      fragment.append(document.createTextNode(text.slice(start,at)));
      const mark=document.createElement('mark');mark.textContent=text.slice(at,at+query.length);fragment.append(mark);start=at+query.length;
    }
    fragment.append(document.createTextNode(text.slice(start)));return fragment;
  }
  function search(query) {
    current=null;
    $('search').value=query;
    $('page-title').textContent='Search results';
    $('page-meta').hidden=true;document.querySelector('.toolbar').hidden=true;
    $('article-view').hidden=true;$('source-view').hidden=true;$('search-results').hidden=false;$('toc').replaceChildren();
    $('contents').hidden=true;
    const terms=query.toLowerCase().split(/\\s+/).filter(Boolean);
    const matches=terms.length?pages.filter(p=>terms.every(t=>(p.title+' '+p.source).toLowerCase().includes(t))).sort((a,b)=>Number(b.title.toLowerCase().includes(query.toLowerCase()))-Number(a.title.toLowerCase().includes(query.toLowerCase()))):[];
    $('result-count').textContent=terms.length?\`\${matches.length} \${matches.length===1?'article':'articles'} matching “\${query}”\${matches.length?'':'. Try fewer words or a broader term.'}\`:'Enter a word or phrase to search all articles.';
    $('results').replaceChildren();
    for (const p of matches) {
      const card=document.createElement('div');card.className='result';
      const small=document.createElement('small');small.textContent=p.section;
      const h=document.createElement('h2'),a=link('',route(p.id));a.append(markText(p.title,query));h.append(a);
      const excerpt=document.createElement('p');
      const plain=p.source.replace(/^---\\n[\\s\\S]*?\\n---\\n/,'').replace(/[#*\`|]/g,'').replace(/\\[([^\\]]+)\\]\\([^)]+\\)/g,'$1').replace(/\\s+/g,' ');
      const position=plain.toLowerCase().indexOf(terms[0]);const start=Math.max(0,position-65);
      excerpt.append(markText((start?'…':'')+plain.slice(start,start+240)+(plain.length>start+240?'…':''),query));
      card.append(small,h,excerpt);$('results').append(card);
    }
    document.title='Search — '+wikiTitle;
  }
  function render() {
    const rawHash=location.hash.slice(1);
    document.querySelectorAll('[aria-current=page]').forEach(a=>a.removeAttribute('aria-current'));
    if(rawHash.startsWith('/search?')) {search(new URLSearchParams(rawHash.slice(8)).get('q')||'');window.scrollTo(0,0);return;}
    let id='index',anchor='';
    try {
      const parts=(rawHash.startsWith('/')?rawHash.slice(1):'index').split('~');
      id=decodeURIComponent(parts[0]);anchor=decodeURIComponent(parts[1]||'');
    } catch {id='__invalid_route__';}

    const p=byId.get(id||'index');
    $('search-results').hidden=true;document.querySelector('.toolbar').hidden=!p;$('page-meta').hidden=!p;
    current=p||null;mode(false);
    if(!p){
      $('page-title').textContent='Page not found';
      $('article').replaceChildren(link('Return to the main page',route('index')));$('toc').replaceChildren();$('backlinks').hidden=true;document.title='Page not found — '+wikiTitle;return;
    }
    $('search').value='';$('page-title').textContent=p.title;
    $('page-meta').innerHTML=p.metadataHtml;
    $('page-meta').hidden=!p.metadataHtml;
    $('article').innerHTML=p.html;
    $('source-text').textContent=p.source;$('source-path').textContent=p.id+'.md';
    $('toc').replaceChildren();
    p.toc.forEach(h=>{const a=link(h.title,route(p.id)+'~'+h.id);if(h.depth>2)a.className='nested';$('toc').append(a);});
    $('backlink-list').replaceChildren();$('backlinks').hidden=!p.backlinks.length;
    p.backlinks.forEach(id=>$('backlink-list').append(link(byId.get(id).title,route(id))));
    document.querySelectorAll('[data-page]').forEach(a=>{if(a.dataset.page===p.id)a.setAttribute('aria-current','page');});
    document.title=p.id==='index'?wikiTitle:p.title+' — '+wikiTitle;
    if(anchor)requestAnimationFrame(()=>{if(anchor===p.titleAnchor)$('page-title').scrollIntoView();else document.getElementById(anchor)?.scrollIntoView();});else window.scrollTo(0,0);
  }
  $('search-form').addEventListener('submit',e=>{e.preventDefault();const hash='/search?q='+encodeURIComponent($('search').value.trim());if(location.hash==='#'+hash)render();else location.hash=hash;});
  $('read-tab').addEventListener('click',()=>mode(false));$('source-tab').addEventListener('click',()=>mode(true));
  $('print').addEventListener('click',()=>{mode(false);window.print();});
  document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();const target=$('search-results').hidden?$('article'):$('main');target.focus();target.scrollIntoView();});
  $('download').addEventListener('click',()=>{
    if(!current)return;const url=URL.createObjectURL(new Blob([current.source],{type:'text/markdown;charset=utf-8'}));
    const a=link('',url);a.download=current.id.split('/').pop()+'.md';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);
  });
  document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)&&!e.metaKey&&!e.ctrlKey&&!e.altKey){e.preventDefault();$('search').focus();}});
  document.addEventListener('click',e=>{const a=e.target.closest('a');if(a?.getAttribute('href')?.startsWith('#/')&&matchMedia('(max-width: 700px)').matches)$('navigation-details').open=false;});
  window.addEventListener('hashchange',render);
  render();
})();
`;

const root = path.dirname(fileURLToPath(import.meta.url));
const escape = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;', '<':'&lt;', '>':'&gt;', '"':'&quot;', "'":'&#39;'}[c]));
const slug = text => text.toLowerCase().replace(/[^\p{L}\p{N}]+/gu, '-').replace(/^-|-$/g, '') || 'section';
const label = text => text.replace(/[-_]+/g, ' ').replace(/^./, c => c.toUpperCase());
const compare = (a,b) => a < b ? -1 : a > b ? 1 : 0;
const route = id => '#/' + id.split('/').map(s=>encodeURIComponent(s).replace(/~/g,'%7E')).join('/');

async function markdownFiles(dir) {
  const entries = await fs.readdir(dir, {withFileTypes:true});
  const result = [];
  for (const entry of entries.sort((a,b)=>compare(a.name,b.name))) {
    // Don't follow symlinks or scan hidden directories/dependency folders.
    if (entry.name.startsWith('.') || entry.name === 'node_modules' || (dir === root && ['attachments','evidence'].includes(entry.name))) continue;
    const file = path.join(dir,entry.name);
    if (entry.isDirectory()) result.push(...await markdownFiles(file));
    else if (entry.isFile() && /\.md$/i.test(entry.name)) result.push(file);
  }
  return result;
}

function readPage(source, id) {
  let body = source.replace(/^\uFEFF/,'').replace(/\r\n?/g,'\n');
  const meta = Object.create(null);
  if (body.startsWith('---\n')) {
    const match = body.match(/^---\n([\s\S]*?)\n---(?:\n|$)([\s\S]*)$/);
    if (!match) throw new Error(`Unclosed front matter: ${id}.md`);
    for (const line of match[1].split('\n')) {
      if (!line.trim() || line.trim().startsWith('#')) continue;
      const i = line.indexOf(':');
      if (i < 1) throw new Error(`Expected key: value metadata in ${id}.md`);
      const key = line.slice(0,i).trim();
      if (Object.hasOwn(meta,key)) throw new Error(`Duplicate ${key} metadata: ${id}.md`);
      meta[key] = line.slice(i+1).trim();
    }
    body = match[2];
  }
  const tokens = new Marked().lexer(body);
  const first = tokens.find(t=>t.type!=='space');
  const titleHeading = first?.type === 'heading' && first.depth === 1 ? first : null;
  const title = meta.title || titleHeading?.text || label(path.posix.basename(id));
  if (meta.title && titleHeading && meta.title !== titleHeading.text) throw new Error(`Title metadata must match first H1: ${id}.md`);
  const section = meta.section || (id.includes('/') ? label(id.split('/')[0]) : 'Overview');
  const order = meta.order ? Number(meta.order) : 0;
  if (!Number.isFinite(order)) throw new Error(`Invalid order: ${id}.md`);
  if (meta.updated && (!/^\d{4}-\d{2}-\d{2}$/.test(meta.updated) || !Number.isFinite(Date.parse(meta.updated)) || new Date(meta.updated).toISOString().slice(0,10)!==meta.updated)) throw new Error(`Invalid updated date: ${id}.md`);
  const presentationKeys=new Set(['title','section','order','updated','summary']);
  const metadata=Object.fromEntries(Object.entries(meta).filter(([key])=>!presentationKeys.has(key)));
  const metadataHtml=Object.entries(metadata).filter(([,value])=>value).map(([key,value])=>`<span>${escape(label(key))}: ${escape(value)}</span>`).concat(meta.updated?[`<span>Last updated: ${escape(meta.updated)}</span>`]:[]).join(' ');
  const toc = [], anchors = [], counts = new Map();
  new Marked().walkTokens(tokens, token => {
    if (token.type === 'heading') {
      const base=slug(token.text), count=counts.get(base)||0;
      counts.set(base,count+1);
      token.anchor=base+(count?`-${count}`:'');
      token.isTitle=token===titleHeading;
      anchors.push(token.anchor);
      if (!token.isTitle) toc.push({id:token.anchor,title:token.text,depth:token.depth});
    }
  });
  return {id,title,section,order,metadata,metadataHtml,updated:meta.updated||'',summary:meta.summary||'',source,tokens,toc,anchors,titleAnchor:titleHeading?.anchor||'',links:[],attachments:[]};
}

const imageExtensions = new Set(['.png','.jpg','.jpeg','.gif','.webp']);
const attachmentExtensions = new Set([...imageExtensions,'.mp4','.webm','.pdf','.txt','.log','.json','.csv']);
const attachmentHref = target => target.split('/').map(encodeURIComponent).join('/');

function localLink(page, href) {
  if (/^[a-z][a-z\d+.-]*:/i.test(href) || href.startsWith('//')) throw new Error(`Unsupported link in ${page.id}.md: ${href}`);
  const hash=href.indexOf('#');
  const file=decodeURIComponent(hash===-1?href:href.slice(0,hash));
  const anchor=hash===-1?'':decodeURIComponent(href.slice(hash+1));
  if (file.startsWith('/') || file.includes('\\') || /[\u0000-\u001f\u007f]/.test(file)) throw new Error(`Use a relative link in ${page.id}.md: ${href}`);
  const target=file?path.posix.normalize(path.posix.join(path.posix.dirname(page.id),file)):page.id+'.md';
  return {file,anchor,target,attachment:!!file&&!/\.md$/i.test(file)};
}

async function collectAttachments(page) {
  const pending=[];
  new Marked().walkTokens(page.tokens, token => {
    if (token.type === 'image' || (token.type === 'link' && !/^https?:\/\//i.test(token.href))) {
      const link=localLink(page,token.href);
      if (token.type === 'image' && !imageExtensions.has(path.posix.extname(link.target).toLowerCase())) throw new Error(`Unsupported image in ${page.id}.md: ${token.href}`);
      if (link.attachment) pending.push(link);
    }
  });
  for (const {target,anchor} of pending) {
    if (!['attachments/','evidence/'].some(prefix=>target.startsWith(prefix)) || !attachmentExtensions.has(path.posix.extname(target).toLowerCase()) || anchor) throw new Error(`Unsupported attachment link in ${page.id}.md: ${target}`);
    if (page.attachments.some(item=>item.path===target)) continue;
    let absolute=root;
    for (const segment of target.split('/')) {
      if (segment.startsWith('.')) throw new Error(`Hidden attachment path in ${page.id}.md: ${target}`);
      absolute=path.join(absolute,segment);
      const info=await fs.lstat(absolute).catch(()=>null);
      if (!info || info.isSymbolicLink()) throw new Error(`Missing or symlinked attachment in ${page.id}.md: ${target}`);
    }
    if (!(await fs.stat(absolute)).isFile()) throw new Error(`Attachment is not a file in ${page.id}.md: ${target}`);
    const digest=createHash('sha256');
    for await (const chunk of createReadStream(absolute)) digest.update(chunk);
    page.attachments.push({path:target,sha256:digest.digest('hex')});
  }
}

async function main() {
  const args=process.argv.slice(2);
  if (args.length===1 && args[0]==='--help') {
    console.log('Usage: node path/to/_build.mjs [--check]\nBuilds Markdown in the script directory into index.html.\n--check validates links, metadata and whether index.html is current.');
    return;
  }
  if (args.some(arg=>arg!=='--check') || args.length>1) throw new Error('Usage: node path/to/_build.mjs [--check | --help]');
  const pages=[];
  for (const file of await markdownFiles(root)) {
    const id=path.relative(root,file).split(path.sep).join('/').replace(/\.md$/i,'');
    if (id==='search') throw new Error('search.md is reserved for the search route; choose another filename.');
    pages.push(readPage(await fs.readFile(file,'utf8'),id));
  }
  const byId=new Map(pages.map(p=>[p.id,p]));
  if (byId.size!==pages.length) throw new Error('Duplicate page paths after removing the .md extension');
  if (!byId.has('index')) throw new Error('Add index.md next to _build.mjs. Its title names the wiki.');
  for (const page of pages) {
    await collectAttachments(page);
    const imageHrefs=new Set();
    const md = new Marked({renderer:{
      heading(token) {
        return token.isTitle ? '' : `<h${token.depth} id="${escape(token.anchor)}">${this.parser.parseInline(token.tokens)}</h${token.depth}>\n`;
      },
      image(token) {
        const resolved=localLink(page,token.href);
        const attachment=page.attachments.find(item=>item.path===resolved.target);
        if (!attachment) throw new Error(`Unvalidated image in ${page.id}.md: ${token.href}`);
        const src=attachmentHref(attachment.path);
        imageHrefs.add(src);
        return `<img src="${escape(src)}" alt="${escape(token.text)}"${token.title?` title="${escape(token.title)}"`:''} loading="lazy" decoding="async">`;
      },
      link(token) {
        const text=this.parser.parseInline(token.tokens);
        if (/^https?:\/\//i.test(token.href)) return `<a href="${escape(token.href)}" rel="noreferrer">${text}</a>`;
        const resolved=localLink(page,token.href);
        const {anchor}=resolved;
        if (resolved.attachment) {
          const attachment=page.attachments.find(item=>item.path===resolved.target);
          if (!attachment) throw new Error(`Unvalidated attachment link in ${page.id}.md: ${token.href}`);
          const href=attachmentHref(attachment.path);
          return `<a href="${escape(href)}" target="_blank" rel="noreferrer" title="SHA-256: ${attachment.sha256}">${text}</a>`;
        }
        const id=resolved.target.replace(/\.md$/i,'');
        const target=byId.get(id);
        if (!target) throw new Error(`Broken link in ${page.id}.md: ${token.href}`);
        if (anchor && !target.anchors.includes(anchor)) throw new Error(`Broken anchor in ${page.id}.md: ${token.href}`);
        page.links.push(id);
        return `<a href="${escape(route(id)+(anchor?'~'+encodeURIComponent(anchor):''))}">${text}</a>`;
      }
    }});
    page.html=sanitizeHtml(md.parser(page.tokens),{
      allowedTags:[...sanitizeHtml.defaults.allowedTags,'img'],
      allowedAttributes:{...sanitizeHtml.defaults.allowedAttributes,h1:['id'],h2:['id'],h3:['id'],h4:['id'],h5:['id'],h6:['id'],code:['class'],a:['href','rel','target','title'],img:['src','alt','title','loading','decoding']},
      // Raw HTML cannot introduce an image that Markdown did not validate.
      exclusiveFilter:frame=>frame.tag==='img'&&!imageHrefs.has(frame.attribs.src),
      allowedSchemes:['http','https'],allowProtocolRelative:false
    });
  }
  const sections=[...new Set(pages.map(p=>p.section))].sort((a,b)=>Number(b==='Overview')-Number(a==='Overview')||compare(a,b));
  pages.sort((a,b)=>sections.indexOf(a.section)-sections.indexOf(b.section)||Number(b.id==='index')-Number(a.id==='index')||a.order-b.order||compare(a.id,b.id));
  const data=pages.map(({tokens,anchors,...page})=>({...page,backlinks:pages.filter(p=>p.id!==page.id&&p.links.includes(page.id)).map(p=>p.id)}));
  const title=byId.get('index').title;
  const json=JSON.stringify({title,pages:data,sections}).replace(/</g,'\\u003c');
  const output=template.replaceAll('/* WIKI_NAME */',()=>escape(title)).replace('/* WIKI_STYLE */',()=>css).replace('/* WIKI_DATA */',()=>json).replace('/* WIKI_SCRIPT */',()=>js);
  const destination=path.join(root,'index.html');
  if (args.includes('--check')) {
    const actual=await fs.readFile(destination,'utf8').catch(error=>{if(error.code==='ENOENT')return '';throw error;});
    if (actual!==output) throw new Error('index.html is missing or stale; run this script without --check.');
    console.log(`Checked ${pages.length} pages and internal links; index.html is current.`);
  } else {
    await fs.writeFile(destination,output);
    console.log(`Built ${destination}: ${pages.length} pages, ${Math.round(Buffer.byteLength(output)/1024)} KB.`);
  }
}
await main().catch(error=>{console.error(error.message);process.exitCode=1;});
